package postgres

import (
	"context"
	"log"
	"time"

	"github.com/jackc/pgx/v5"
)

// WatchRealtimeNotifications follows committed notifications generated by
// realtime_append. LISTEN runs on a dedicated connection, not a pooled
// application query slot. Payloads are wake-up hints only; durable replay
// enforces authorization and event ordering.
func WatchRealtimeNotifications(ctx context.Context, dsn string, wake chan<- struct{}) {
	delay := 200 * time.Millisecond
	for ctx.Err() == nil {
		conn, err := pgx.Connect(ctx, dsn)
		if err == nil {
			_, err = conn.Exec(ctx, "LISTEN filesmanage_realtime")
		}
		if err == nil {
			// Pick up commits during initial LISTEN and every reconnect.
			signalRealtimeWake(wake)
			delay = 200 * time.Millisecond
			for ctx.Err() == nil {
				if _, err = conn.WaitForNotification(ctx); err != nil {
					break
				}
				signalRealtimeWake(wake)
			}
		}
		if conn != nil {
			closeCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
			_ = conn.Close(closeCtx)
			cancel()
		}
		if ctx.Err() != nil {
			return
		}
		log.Printf("realtime LISTEN retry: %v", err)
		select {
		case <-ctx.Done():
			return
		case <-time.After(delay):
		}
		if delay < 5*time.Second {
			delay *= 2
		}
	}
}

// One buffered wake coalesces bursts without blocking the PG connection.
func signalRealtimeWake(wake chan<- struct{}) {
	select {
	case wake <- struct{}{}:
	default:
	}
}
